// Run: npm test. Guards the *built* service worker (#4648) — the file the
// browser actually runs. public/sw.js is generated by `npm run build`
// (next-pwa), so this asserts on the generated routes, not on the config that
// produced them. lib/pwa/caching-policy.test.mjs covers the policy itself;
// this covers "did next-pwa compile it the way we meant".
//
// The central assertion is behavioural rather than textual: each generated
// route's match function is lifted out of the minified worker and RUN against a
// list of real URLs. A route that caches may not match a `/bff` or `/api` URL,
// whatever its code looks like.
//
// public/sw.js is gitignored and absent until a build, so the built-worker
// assertions are skipped when it is missing and say so. CI builds before the
// e2e job; `npm run build && npm test` is the full check.
import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { createRequire } from "node:module";

const here = new URL(".", import.meta.url).pathname;
const ui = join(here, "..");
const swPath = join(ui, "public", "sw.js");
const require = createRequire(import.meta.url);
const policy = require(join(ui, "lib", "pwa", "caching-policy.js"));

const ORIGIN = "https://home.example";
const built = existsSync(swPath);
const sw = built ? readFileSync(swPath, "utf8") : "";
const skip = built ? false : "public/sw.js is not built yet: run npm run build";

/** Every authenticated URL class the app issues, plus the bare prefixes. */
const AUTHENTICATED = [
  "/bff",
  "/bff/",
  "/bff/auth/me",
  "/bff/members",
  "/bff/bills?month=2026-11",
  "/bff/notes",
  "/bff/secrets/key",
  "/bff/files/3f8a/content",
  "/bff/notifications",
  "/api",
  "/api/",
  "/api/auth/login",
  "/api/auth/callback?code=x&state=y",
  "/api/auth/logout",
];

/**
 * Every `registerRoute(...)` in the built worker as
 * { matcher, handler, cacheName, matches(url) }.
 *
 * Minified, a call reads
 *   registerRoute(({url:s})=>{...},new s.NetworkOnly,"GET")
 * so the arguments are split on balanced parens (a matcher body contains both
 * parens and braces, which regexes cannot navigate).
 */
function routes(source) {
  const found = [];
  const marker = "registerRoute(";
  for (let at = source.indexOf(marker); at !== -1; at = source.indexOf(marker, at + 1)) {
    const open = at + marker.length - 1;
    let depth = 0;
    let close = open;
    for (; close < source.length; close += 1) {
      const ch = source[close];
      if (ch === "(") depth += 1;
      else if (ch === ")" && (depth -= 1) === 0) break;
    }
    const call = source.slice(at, close + 1);
    // Split the arguments at depth 0.
    const args = source.slice(open + 1, close);
    const parts = [];
    let current = "";
    let nesting = 0;
    for (const ch of args) {
      if ("([{".includes(ch)) nesting += 1;
      else if (")]}".includes(ch)) nesting -= 1;
      if (ch === "," && nesting === 0) {
        parts.push(current);
        current = "";
      } else current += ch;
    }
    parts.push(current);

    const matcher = parts[0] || "";
    const handler = (parts[1] || "").match(/\.(\w+)/);
    const cacheName = call.match(/cacheName:"([^"]+)"/);
    found.push({
      matcher,
      handler: handler ? handler[1] : null,
      cacheName: cacheName ? cacheName[1] : null,
      // Run the generated matcher for real, the way workbox-routing does.
      // A capture is a function, a RegExp (RegExpRoute) or a string (exact
      // href/match); all three have to be handled, or a default rule that uses
      // one would silently look like "no match".
      matches(url) {
        const parsed = new URL(url, ORIGIN);
        const sameOrigin = parsed.origin === ORIGIN;
        const context = { url: parsed, sameOrigin, request: { method: "GET", url: parsed.href }, event: {} };
        // eslint-disable-next-line no-new-func
        const capture = new Function("self", `return (${matcher});`)({
          origin: ORIGIN,
          // next-pwa's defaults referenced self.origin and location.
          location: { origin: ORIGIN, href: `${ORIGIN}/` },
        });
        if (typeof capture === "function") return !!capture(context);
        if (capture instanceof RegExp) {
          // RegExpRoute: the match must start at 0 for a cross-origin URL.
          const result = capture.exec(parsed.href);
          return !!result && (sameOrigin || result.index === 0);
        }
        // A string capture is an exact href match (registerRoute's own rule).
        return parsed.href === new URL(capture, ORIGIN).href;
      },
    });
  }
  return found;
}

// ── the config that produces the worker ────────────────────────────────────

test("next.config.js passes the policy to next-pwa, never its defaults", () => {
  const source = readFileSync(join(ui, "next.config.js"), "utf8");
  assert.match(source, /runtimeCaching/, "runtimeCaching is passed explicitly");
  assert.ok(!/require\(["']next-pwa\/cache["']\)/.test(source), "next-pwa's default cache list is not imported");
  // next-pwa caches outside runtimeCaching when these are on, so all three are off.
  for (const option of ["dynamicStartUrl", "cacheStartUrl", "cacheOnFrontEndNav"]) {
    assert.match(source, new RegExp(`${option}: false`), `${option} is off`);
  }
});

// ── the built worker ───────────────────────────────────────────────────────

test("public/sw.js exists and is a generated Workbox worker", { skip }, () => {
  assert.ok(sw.length > 1000, "a real generated worker");
  assert.match(sw, /precacheAndRoute/, "precaching is still there");
  assert.equal(routes(sw).length, policy.runtimeCaching.length, "one route per policy rule");
});

test("NO caching route matches a /bff or /api URL", { skip }, () => {
  // The rule that matters, tested by running the generated matchers.
  for (const route of routes(sw)) {
    if (route.handler === "NetworkOnly") continue;
    for (const path of AUTHENTICATED) {
      assert.equal(
        route.matches(path),
        false,
        `${route.cacheName} (${route.handler}) must not match ${path}`,
      );
    }
  }
});

test("a NetworkOnly route matches every /bff and /api URL, and it comes first", { skip }, () => {
  const all = routes(sw);
  const guard = all[0];
  assert.equal(guard.handler, "NetworkOnly", "the first generated route is the guard");
  assert.equal(guard.cacheName, null, "and it names no cache");
  for (const path of AUTHENTICATED) {
    assert.equal(guard.matches(path), true, `the guard matches ${path}`);
  }
  // ...and it is the only route matching them.
  for (const route of all.slice(1)) {
    for (const path of AUTHENTICATED) {
      assert.equal(route.matches(path), false, `route ${route.cacheName ?? route.handler} does not match ${path}`);
    }
  }
});

test("the caching routes still cache what they are meant to", { skip }, () => {
  // Guards against a matcher that matches nothing at all (which would pass the
  // test above for the wrong reason).
  const byCache = Object.fromEntries(routes(sw).filter((r) => r.cacheName).map((r) => [r.cacheName, r]));
  assert.ok(byCache["home-os-static"].matches("/_next/static/chunks/main-abc123.js"));
  assert.ok(byCache["home-os-assets"].matches("/icons/icon-192.png"));
  assert.ok(byCache["home-os-assets"].matches("/manifest.json"));
  assert.ok(byCache["home-os-font-styles"].matches("https://fonts.googleapis.com/css2?family=Fira+Sans"));
  assert.ok(byCache["home-os-font-files"].matches("https://fonts.gstatic.com/s/firasans/v1/a.woff2"));
});

test("pages are not intercepted by the built worker (offline shell is #4538)", { skip }, () => {
  for (const path of ["/", "/dashboard", "/dashboard/bills?month=2026-11", "/login", "/settings"]) {
    for (const route of routes(sw)) {
      assert.equal(route.matches(path), false, `${route.cacheName ?? route.handler} must not intercept ${path}`);
    }
  }
});

test("no generated caching strategy names a next-pwa default cache", { skip }, () => {
  // "others" held /bff responses and "apis" held /api ones before #4648.
  const names = routes(sw).map((r) => r.cacheName).filter(Boolean);
  for (const name of ["others", "apis", "start-url", "cross-origin", "next-data", "static-assets", "next-image"]) {
    assert.ok(!names.includes(name), `the built worker creates no "${name}" cache`);
  }
});

test("every cache the built worker creates is on the policy's allowlist", { skip }, () => {
  const names = routes(sw).map((r) => r.cacheName).filter(Boolean);
  assert.ok(names.length > 0, "the static rules do name caches");
  // Exactly the policy's caches: none missing, none extra.
  assert.deepEqual([...new Set(names)].sort(), [...policy.CACHE_NAMES].sort());
});

test("the built worker does not seed caches from register.js", { skip }, () => {
  // next-pwa's register.js seeds a "start-url" cache and, with
  // cacheOnFrontEndNav, an "others" cache from pushState — neither goes through
  // runtimeCaching. Off in next.config.js, so the strings must not appear.
  assert.ok(!sw.includes('"start-url"'), "no start-url cache in the worker");
  assert.ok(!sw.includes("networkTimeoutSeconds"), "no next-pwa default NetworkFirst timings");
});

// ── the custom worker half ─────────────────────────────────────────────────

test("the built worker imports the custom worker that purges unknown caches", { skip }, () => {
  // worker/index.js compiles to public/worker-<buildId>.js and is imported
  // before the Workbox routes, so its activate handler deletes caches left by
  // older builds. next-pwa's AMD shim calls importScripts() itself too, so
  // match on the argument.
  assert.match(sw, /importScripts\("worker-[\w-]+\.js"\)/, "the custom worker is imported by name");
  const custom = readdirSync(join(ui, "public")).filter((f) => /^worker-.*\.js$/.test(f));
  assert.equal(custom.length, 1, "exactly one custom worker was written");
  const code = readFileSync(join(ui, "public", custom[0]), "utf8");
  assert.match(code, /PURGE_CACHES/, "the message handler is in the build");
  assert.match(code, /addEventListener\("activate"/, "and the activate purge");
  for (const name of policy.CACHE_NAMES) {
    assert.ok(code.includes(`"${name}"`), `${name} is on the worker's allowlist`);
  }
});
